"""Independent ASQBI small-strain prediction, not a repair of A27's failed gate."""
from run_aircraft_a28 import *

def main():
    guard();dest=OUT/'assumed_strain_diagnostic.json';assert not dest.exists();c=read(CFG);E=22000.;nu=.25;Ez=10000.;plane=E/(1-nu*nu);beta=nu/(1-nu);extra=Ez*beta*beta;rows=[]
    for rev,layers in [('w1',3),('w2',3),('w3',9)]:
        for mesh in [6,12]:
            d=PREV/rev/f'BENDING_N{mesh}';g=read(d/'generation.json');r=read(d/'review.json');H=histories(d/(g['name']+'T01.csv'));T=H['time'];tt=np.linspace(0,.1,1001);ramp=3*(tt/.1)**2-2*(tt/.1)**3;s=np.interp(T,tt,ramp);z=np.array([(i+.5)/layers-.5 for i in range(layers)])*.5;weights=np.ones(layers)/layers;second=float(np.dot(weights,z*z));pref=.5*.001**2*50*second*.001;classic=pref*plane*s*s;enhanced=pref*(plane+extra)*s*s;IE=H['INTERNAL ENERGY']*.001;error=abs(IE-enhanced);tol=.02*np.maximum(abs(IE),abs(enhanced))+1e-7
            rows.append({'revision':rev,'mesh_n':mesh,'layers':layers,'native_history':rel(d/(g['name']+'T01.csv')),'native_history_sha256':streamsha(d/(g['name']+'T01.csv')),'old_review':rel(d/'review.json'),'old_review_sha256':streamsha(d/'review.json'),'old_independent_bending_gate_unchanged':r['checks']['independent_elastic_reference'],'native_last_ms':float(T[-1]),'native_final_IE_J':float(IE[-1]),'classical_layer_quadrature_final_J':float(classic[-1]),'ASQBI_transverse_prediction_final_J':float(enhanced[-1]),'extra_transverse_prediction_final_J':float((enhanced-classic)[-1]),'maximum_all_history_difference_J':float(error.max()),'maximum_normalized_difference':float((error/tol).max()),'ASQBI_prediction_matches_original_tolerance':bool(np.all(error<tol)),'source_material_and_geometry_unmodified':True})
    # Preserve both independently documented constitutive descriptions.
    S=np.array([[1/E,-nu/E,-nu/Ez],[-nu/E,1/E,-nu/E],[-nu/Ez,-nu/E,1/Ez]]);full=np.linalg.inv(S)
    a={'created_utc':now(),'iteration':'AIRCRAFT-A28','method':'Pure xz bending activates ASQBI xz hourglass mode: epsilon_xx=-k*z, epsilon_yy=0, epsilon_zz=-nu/(1-nu)*epsilon_xx. Applying explicitly declared TYPE22 block stiffness produces E33*(nu/(1-nu))² extra stiffness, independent of native energy. Numerical layers integrate z² at their centers. No modulus or coefficient inferred from native outputs.',
      'documented_sources':['https://help.altair.com/hwsolvers/rad/topics/solvers/rad/theory_element_assumed_strain_rate.htm','https://help.altair.com/hwsolvers/rad/topics/solvers/rad/law25_composite_material_r.htm'],
      'C_plane_MPa':plane,'assumed_transverse_strain_ratio':beta,'extra_C_MPa':extra,'relative_extra_C':extra/plane,'fully_3D_theory_normal_stiffness_material_axes_MPa':full.tolist(),'thick_shell_block_normal_stiffness_global_MPa':constitutive()[:3,:3].tolist(),'general_3D_equivalence_still_unqualified':True,'cases':rows,'cached_native_cases_read':len(rows),'native_old_solver_reruns':0,'old_failed_reviews_preserved':True,'prediction_matches_all':all(r['ASQBI_prediction_matches_original_tolerance'] for r in rows),'qualification':'Explanation supported by formulation and cached outputs; direct diagnostic perturbation and alternative formulation remain independent new tests, not historical validation. A27 failure is retained.'};dump(dest,a);print({'A28_cached_ASQBI_prediction':a['prediction_matches_all'],'cases':len(rows),'extra_stiffness_fraction':extra/plane},flush=True)

